#include "resident/domains/military/military_model.hpp"
// 具名操作只写原Military17账；原钱货/占领/旅行在外层同事务执行，任何晚失败均不得发布此账。
#include "military_siege_engineering_access.hpp"
#include <algorithm>
namespace hanmo::resident {
MilitarySiegeEngineeringAccess::MilitarySiegeEngineeringAccess(CommonStore& c,MilitaryState& m,const MilitaryCatalog& catalog,const MilitarySiegeEngineeringSkillRead& skills,const DynamicStepInput* phase):common_(c),military_(m),catalog_(catalog),skills_(skills),phase_(phase?std::optional<DynamicStepInput>{*phase}:std::nullopt){}
Status MilitarySiegeEngineeringAccess::selected(const StableId& topology)const{const auto& p=catalog_.siege_engineering_policy;if(!p||std::find(p->topology_ids.begin(),p->topology_ids.end(),topology)==p->topology_ids.end())return common_failure("MilitarySiegeEngineeringProfileRequired",topology);return validate_military_siege_engineering_rule(p->rule);}
Outcome<std::optional<MilitarySiegeTimeoutRelease>> MilitarySiegeEngineeringAccess::timeout_release(const MilitaryBattleRecord& b)const{if(!phase_)return {false,{},common_failure("MilitarySiegeTimeoutPhaseRequired",b.id).error};return read_military_siege_timeout_release(common_.state(),military_,catalog_,b,*phase_);}
Outcome<MilitarySiegeEngineeringPreparation> MilitarySiegeEngineeringAccess::preview(const SiegeRecord& s)const{auto checked=selected(s.topology_id);if(!checked.ok)return {false,{},checked.error};return phase_?preview_military_siege_engineering_preparation(common_,military_,catalog_,s,skills_,*phase_):preview_current_military_siege_engineering_preparation(common_,military_,catalog_,s,skills_);}
Outcome<MilitarySiegeEngineeringPreparation> MilitarySiegeEngineeringAccess::prepare(const SiegeRecord& s,Integer tick){auto checked=selected(s.topology_id);if(!checked.ok)return {false,{},checked.error};if(!phase_||tick!=phase_->to_tick)return {false,{},common_failure("MilitarySiegeEngineeringPhaseRequired",s.id).error};return prepare_military_siege_engineering(common_,military_,catalog_,s,military_.siege_engineering,skills_,*phase_);}
Outcome<SiegeRecord> MilitarySiegeEngineeringAccess::create(const SiegeCreateRequest& r,const SiegeTopology& t,const SiegeObservation& o,const StableId& actor,const StableId& arrival){auto checked=selected(t.id);return !checked.ok?Outcome<SiegeRecord>{false,{},checked.error}:create_military_siege_with_lifecycle(common_,military_.siege_lifecycle,r,t,o,actor,arrival);}
Outcome<SiegeRecord> MilitarySiegeEngineeringAccess::join(const SiegeRecord& s,const SiegeTopology& t,const SiegeObservation& o,const StableId& actor,const StableId& army,Integer side,const StableId& arrival){auto checked=selected(t.id);return !checked.ok?Outcome<SiegeRecord>{false,{},checked.error}:join_military_siege_with_lifecycle(common_,military_.siege_lifecycle,s,t,o,actor,army,side,arrival);}
Outcome<SiegeResolution> MilitarySiegeEngineeringAccess::step(const SiegeRecord& s,const SiegeTopology& t,const SiegeObservation& o,const StableId& actor,const SiegeOrders& orders,Integer tick){auto checked=selected(t.id);if(!checked.ok)return {false,{},checked.error};if(!phase_||tick!=phase_->to_tick)return {false,{},common_failure("MilitarySiegeEngineeringPhaseRequired",s.id).error};return step_military_siege_with_lifecycle(common_,military_.siege_lifecycle,s,t,o,actor,orders,*phase_);}
Outcome<SiegeRecord> MilitarySiegeEngineeringAccess::finish_battle(const SiegeRecord& s,const SiegeTopology& t,const SiegeObservation& o,const StableId& node,const StableId& battle){auto checked=selected(t.id);return !checked.ok?Outcome<SiegeRecord>{false,{},checked.error}:finish_military_siege_battle_with_lifecycle(common_,military_.siege_lifecycle,s,t,o,node,battle,phase_?&*phase_:nullptr);}
Outcome<SiegeResolution> MilitarySiegeEngineeringAccess::manage(const SiegeRecord& s,const SiegeTopology& t,const SiegeObservation& o,const StableId& actor,const SiegeStrategicCommand& command){auto checked=selected(t.id);return !checked.ok?Outcome<SiegeResolution>{false,{},checked.error}:manage_military_siege_with_lifecycle(common_,military_.siege_lifecycle,s,t,o,actor,command);}
Outcome<SiegeResolution> MilitarySiegeEngineeringAccess::terminate(const SiegeRecord& s,const SiegeTopology& t,const SiegeObservation& o,const StableId& reason){auto checked=selected(t.id);return !checked.ok?Outcome<SiegeResolution>{false,{},checked.error}:terminate_military_siege_with_lifecycle(common_,military_.siege_lifecycle,s,t,o,reason,phase_?&*phase_:nullptr);}
Outcome<SiegeRecord> MilitarySiegeEngineeringAccess::close(const SiegeRecord& s,const SiegeTopology& t,const StableId& actor){auto checked=selected(t.id);if(!checked.ok)return {false,{},checked.error};const MilitarySiegeReleaseFact* release=nullptr;for(const auto& f:military_.recovery.siege_releases)if(f.siege_id==s.id){if(release)return {false,{},common_failure("MilitarySiegeReleaseRepeated",s.id).error};release=&f;}if(!release||release->actor_id!=actor||release->tick!=common_.tick())return {false,{},common_failure("MilitarySiegeLifecycleCloseSourceRequired",s.id).error};return close_military_siege_with_lifecycle(common_,military_.siege_lifecycle,s,t,actor,release->id);}
Status MilitarySiegeEngineeringAccess::departed(const SiegeRecord& before,const SiegeRecord& after,const SiegeTopology& t){auto checked=selected(t.id);return !checked.ok?checked:record_departed_military_siege_lifecycle(common_,military_.siege_lifecycle,before,after,t);}
Status MilitarySiegeEngineeringAccess::integrated(const SiegeRecord& before,const SiegeRecord& after,const SiegeTopology& t,const StableId& transfer,Integer tick){auto checked=selected(t.id);return !checked.ok?checked:record_integrated_military_siege_lifecycle(common_,military_.siege_lifecycle,before,after,t,transfer,tick);}
}
